import json
from collections import Counter, defaultdict

VALID = {'PER', 'ORG', 'LOC', 'TIME', 'NUM', 'MISC'}
ALIASES = {
    'PERSON': 'PER', 'PEOPLE': 'PER',
    'ORGANIZATION': 'ORG', 'ORGANISATION': 'ORG',
    'LOCATION': 'LOC', 'NUMBER': 'NUM', 'NUMERICAL': 'NUM',
    'MISCELLANEOUS': 'MISC',
}

def norm_et(raw):
    t = raw.strip().upper()
    return ALIASES.get(t, t)

def analyze(path, label):
    ent_only_oov = Counter()
    rel_only_oov = Counter()
    total_et_viol = 0
    with open(path) as f:
        for line in f:
            rec = json.loads(line)
            parsed = rec.get('parsed_output')
            if not parsed:
                continue
            seen = {}
            # entity list
            for ent in parsed.get('entities', []):
                text = ent.get('text', '?')
                etype = ent.get('type', '')
                norm = norm_et(etype)
                key = (text.lower().strip(), norm)
                if key not in seen:
                    seen[key] = ('entity', etype)

            ent_keys = set(seen.keys())

            # relations
            for rel in parsed.get('relations', []):
                for role in [('head', 'head_type'), ('tail', 'tail_type')]:
                    text = rel.get(role[0], '')
                    rtype = rel.get(role[1], '')
                    if text and rtype:
                        norm = norm_et(rtype)
                        key = (text.lower().strip(), norm)
                        if key not in seen:
                            seen[key] = ('relation', rtype)

            for (_, norm_type), (source, raw_type) in seen.items():
                if norm_type not in VALID:
                    total_et_viol += 1
                    if source == 'entity':
                        ent_only_oov[raw_type] += 1
                    else:
                        rel_only_oov[raw_type] += 1

    print(f'=== {label} ===')
    print(f'Total ET violations (v2 method): {total_et_viol}')
    print(f'  From entity list: {sum(ent_only_oov.values())}')
    print(f'  From relation head/tail_type only: {sum(rel_only_oov.values())}')
    print(f'  Entity-list OOV types: {ent_only_oov.most_common(10)}')
    print(f'  Relation-only OOV types: {rel_only_oov.most_common(15)}')
    print()

analyze('outputs/docred_unconstrained.jsonl', 'DocRED Unconstrained')
analyze('outputs/docred_semantic_only.jsonl', 'DocRED Semantic-only')
analyze('outputs/phase2_scierc_unconstrained.jsonl', 'SciERC Unconstrained')
analyze('outputs/phase2_scierc_semantic_only.jsonl', 'SciERC Semantic-only')
